-- Schemat danych punktów (U2). Odpowiada modelom Django z djangoapp/pointsdb/models.py
-- (te same ograniczenia unikalności). Identyfikatory są przenoszone z obecnej bazy
-- przy imporcie (U5), dlatego kolumny id to "generated by default as identity".

create extension if not exists vector with schema extensions;
create extension if not exists unaccent with schema extensions; -- używane w U3

-- MarmaPoint + opis punktu (dokument RethinkDB) w kolumnie doc.
create table public.marma_points (
  id bigint generated by default as identity primary key,
  name varchar(255) not null,
  alt_name varchar(255),
  location varchar(255) not null,
  doshic_subtypes varchar(255),
  doc jsonb not null default '{}'::jsonb
);

-- MarmaPointCoordinates: unique_together = (marma_point, label).
create table public.marma_point_coordinates (
  id bigint generated by default as identity primary key,
  marma_point_id bigint not null references public.marma_points (id) on delete cascade,
  label varchar(255) not null,
  x double precision not null,
  y double precision not null,
  z double precision not null,
  unique (marma_point_id, label)
);

-- MarmaPointFunction: function_name unique.
create table public.marma_point_functions (
  id bigint generated by default as identity primary key,
  function_name varchar(255) not null unique,
  subject_type varchar(255) not null,
  marmani_description text not null
);

-- Subject.
create table public.subjects (
  id bigint generated by default as identity primary key,
  name varchar(255) not null
);

-- MarmaPointSubject: unique_together = (marma_point, subject, function).
create table public.marma_point_subjects (
  id bigint generated by default as identity primary key,
  marma_point_id bigint not null references public.marma_points (id) on delete cascade,
  subject_id bigint not null references public.subjects (id) on delete cascade,
  function_id bigint not null references public.marma_point_functions (id) on delete cascade,
  notes text,
  unique (marma_point_id, subject_id, function_id)
);

create index marma_point_subjects_subject_id_idx on public.marma_point_subjects (subject_id);
create index marma_point_subjects_function_id_idx on public.marma_point_subjects (function_id);

-- Wektory tematów (odpowiednik kolekcji Qdrant): wersje EN i PL w jednej tabeli.
-- Bez indeksu wektorowego: ok. 1800 wierszy, pełny skan daje 100% trafności.
create table public.subject_embeddings (
  id bigint generated by default as identity primary key,
  subject_id bigint not null references public.subjects (id) on delete cascade,
  is_polish boolean not null,
  embedding extensions.vector(1536) not null
);

create index subject_embeddings_subject_id_idx on public.subject_embeddings (subject_id);
